const x=(n,t,a)=>n<t?t:n>a?a:n;export function spanFor(n,t){const a=x((n-.5)/.8,0,1);return t.narrowSpan+(t.wideSpan-t.narrowSpan)*a}export function distanceFor(n,t,a){const e=Math.atan(Math.tan(a*Math.PI/360)*t);return n/2/Math.tan(e)}export function cameraFor(n,t,a,e){const r=spanFor(n,t),o=distanceFor(r,n,t.fovDegrees),u=Math.hypot(t.height,t.back),z=t.height/u,i=t.back/u,p=Math.max(0,(a.maxX-a.minX)/2-r/2+1),h=(a.minX+a.maxX)/2;let c=t.target.x,s=t.target.z;if(e){c=x(e.x,h-p,h+p);const y=1-x((n-.5)/.8,0,1);s=t.target.z+(e.z-t.target.z)*.5*y}return{position:{x:c,y:t.target.y+z*o,z:s+i*o},target:{x:c,y:t.target.y,z:s},span:r,distance:o}}export function rayToGround(n,t){if(t.y>=-1e-6)return null;const a=-n.y/t.y;return{x:n.x+t.x*a,z:n.z+t.z*a}}export function ease(n,t,a,e){return t+(n-t)*Math.exp(-a*e)}
